import{_ as t,a0 as d,w as o,s as r,ao as l,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 上动态链接模块库 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上动态链接模块库 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上动态链接模块库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上动态链接模块库 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220531 How dynamic linking for modular libraries works on Linux","title":"如何在 Linux 上动态链接模块库","tag":"202207","desc":""},"relativePath":"202207/20220531 How dynamic linking for modular libraries works on Linux.md","filePath":"[post].md"}'),c={name:"202207/20220531 How dynamic linking for modular libraries works on Linux.md"};function h(u,s,b,g,k,m){const n=d("Link");return o(),r("div",null,[s[27]||(s[27]=l('<h1 id="如何在-linux-上动态链接模块库" tabindex="-1">如何在 Linux 上动态链接模块库 <a class="header-anchor" href="#如何在-linux-上动态链接模块库" aria-label="Permalink to “如何在 Linux 上动态链接模块库”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/10/182540caie7ldrefflffah.jpg" alt=""></p><blockquote><p>学习如何用动态链接库将多个 C 目标文件结合到一个单个的可执行文件之中。</p></blockquote><p>当使用 C 编程语言编写一个应用程序时，你的代码通常有多个源文件代码。</p><p>最终，这些文件必须被编译到一个单个的可执行文件之中。你可以通过创建静态或动态库（后者也被称为 <ruby>共享<rt>shared</rt></ruby> 库）来实现这一点。这两种类型的库在创建和链接的方式上有所不同。两者都有缺点和优点，这取决于你的使用情况。</p><p>动态链接是最常见的方法，尤其是在 Linux 系统上。动态链接会保持库模块化，因此，很多应用程序可以共享一个库。应用程序的模块化也允许单独更新其依赖的共享库。</p><p>在这篇文章中，我将演示动态链接是如何工作的。在后期的文章中，我将演示静态链接。</p><h3 id="链接器" tabindex="-1">链接器 <a class="header-anchor" href="#链接器" aria-label="Permalink to “链接器”">​</a></h3><p><ruby>链接器<rt>linker</rt></ruby>是一个命令，它将一个程序的数个部分结合在一起，并为它们重新组织内存分配。</p><p>链接器的功能包括：</p><ul><li>整合一个程序的所有的部分</li><li>计算出一个新的内存组织结构，以便所有的部分组合在一起</li><li>恢复内存地址，以便程序可以在新的内存组织结构下运行</li><li>解析符号引用</li></ul>',11)),i("p",null,[s[1]||(s[1]=a("链接器通过这些功能，创建了一个名为",-1)),s[2]||(s[2]=i("ruby",null,[a("可执行文件"),i("rt",null,"executable")],-1)),s[3]||(s[3]=a("的可以运行的程序。在你创建一个动态链接的可执行文件前，你需要一些用来链接的库，和一个用来编译的应用程序。准备好你 ",-1)),e(n,{href:"https://opensource.com/article/21/2/open-source-text-editors"},{default:p(()=>[...s[0]||(s[0]=[a("最喜欢的文本编辑器",-1)])]),_:1}),s[4]||(s[4]=a(" 并继续。",-1))]),s[28]||(s[28]=l(`<h3 id="创建目标文件" tabindex="-1">创建目标文件 <a class="header-anchor" href="#创建目标文件" aria-label="Permalink to “创建目标文件”">​</a></h3><p>首先，创建带有这些函数签名的头文件 <code>mymath.h</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int sub(int a, int b);</span></span>
<span class="line"><span>int mult(int a, int b);</span></span>
<span class="line"><span>int divi(int a, int b);</span></span></code></pre></div><p>使用这些函数定义来创建 <code>add.c</code> 、<code>sub.c</code> 、<code>mult.c</code> 和 <code>divi.c</code> 文件。我将把所有的代码都放置到一个代码块中，请将其分为四个文件，如注释所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// add.c</span></span>
<span class="line"><span>int add(int a, int b){</span></span>
<span class="line"><span>return (a+b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//sub.c</span></span>
<span class="line"><span>int sub(int a, int b){</span></span>
<span class="line"><span>return (a-b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//mult.c</span></span>
<span class="line"><span>int mult(int a, int b){</span></span>
<span class="line"><span>return (a*b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//divi.c</span></span>
<span class="line"><span>int divi(int a, int b){</span></span>
<span class="line"><span>return (a/b);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在，使用 GCC 来创建目标文件 <code>add.o</code>、<code>sub.o</code>、<code>mult.o</code> 和 <code>divi.o</code> ：</p><p>（LCTT 校注：关于“<ruby>目标文件<rt>object file</rt></ruby>”，有时候也被称作“对象文件”，对此，存在一些译法混乱情形，称之为“目标文件”的译法比较流行，本文采用此译法。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -c add.c sub.c mult.c divi.c</span></span></code></pre></div><p><code>-c</code> 选项跳过链接步骤，并且只创建目标文件。</p><h3 id="创建一个共享的目标文件" tabindex="-1">创建一个共享的目标文件 <a class="header-anchor" href="#创建一个共享的目标文件" aria-label="Permalink to “创建一个共享的目标文件”">​</a></h3><p>在最终的可执行文件的执行过程中将链接动态库。在最终的可执行文件中仅放置动态库的名称。实际上的链接过程发生在运行时，在此期间，可执行文件和库都被放置到了主内存中。</p><p>除了可共享外，动态库的另外一个优点是它减少了最终的可执行文件的大小。在一个应用程序最终的可执行文件生成时，其使用的库只包括该库的名称，而不是该库的一个多余的副本。</p><p>你可以从你现有的示例代码中创建动态库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -Wall -fPIC -c add.c sub.c mult.c divi.c</span></span></code></pre></div><p>选项 <code>-fPIC</code> 告诉 GCC 来生成<ruby>位置无关的代码<rt>position-independent code</rt></ruby>（PIC）。<code>-Wall</code> 选项不是必需的，并且与代码的编译方式是无关的。不过，它却是一个有价值的选项，因为它会启用编译器警告，这在排除故障时是很有帮助的。</p><p>使用 GCC ，创建共享库 <code>libmymath.so</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -shared -o libmymath.so add.o sub.o mult.o divi.o</span></span></code></pre></div><p>现在，你已经创建了一个简单的示例数学库 <code>libmymath.so</code> ，你可以在 C 代码中使用它。当然，也有非常复杂的 C 库，这就是他们这些开发者来生成最终产品的工艺流程，你和我可以安装这些库并在 C 代码中使用。</p><p>接下来，你可以在一些自定义代码中使用你的新数学库，然后链接它。</p><h3 id="创建一个动态链接的可执行文件" tabindex="-1">创建一个动态链接的可执行文件 <a class="header-anchor" href="#创建一个动态链接的可执行文件" aria-label="Permalink to “创建一个动态链接的可执行文件”">​</a></h3><p>假设你已经为数学运算编写了一个命令。创建一个名称为 <code>mathDemo.c</code> 的文件，并将这些代码复制粘贴至其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;mymath.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  int x, y;</span></span>
<span class="line"><span>  printf(&quot;Enter two numbers\\n&quot;);</span></span>
<span class="line"><span>  scanf(&quot;%d%d&quot;,&amp;x,&amp;y);</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>  printf(&quot;\\n%d + %d = %d&quot;, x, y, add(x, y));</span></span>
<span class="line"><span>  printf(&quot;\\n%d - %d = %d&quot;, x, y, sub(x, y));</span></span>
<span class="line"><span>  printf(&quot;\\n%d * %d = %d&quot;, x, y, mult(x, y));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  if(y==0){</span></span>
<span class="line"><span>    printf(&quot;\\nDenominator is zero so can&#39;t perform division\\n&quot;);</span></span>
<span class="line"><span>      exit(0);</span></span>
<span class="line"><span>  }else{</span></span>
<span class="line"><span>      printf(&quot;\\n%d / %d = %d\\n&quot;, x, y, divi(x, y));</span></span>
<span class="line"><span>      return 0;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,22)),i("p",null,[s[6]||(s[6]=a("注意：第一行是一个 ",-1)),s[7]||(s[7]=i("code",null,"include",-1)),s[8]||(s[8]=a(" 语句，通过名称来引用你自己的 ",-1)),s[9]||(s[9]=i("code",null,"libmymath",-1)),s[10]||(s[10]=a(" 库。要使用一个共享库，你必须已经安装了它，如果你没有安装你将要使用的库，那么当你的可执行文件在运行并搜索其包含的库时，将找不到该共享库。如果你需要在不安装库到已知目录的情况下编译代码，这里有 ",-1)),e(n,{href:"https://opensource.com/article/22/5/compile-code-ldlibrarypath"},{default:p(()=>[...s[5]||(s[5]=[a("一些方法可以覆盖默认设置",-1)])]),_:1}),s[11]||(s[11]=a("。不过，对于一般使用来说，我们希望库存在于已知的位置，因此，这就是我在这里演示的东西。",-1))]),s[29]||(s[29]=l(`<p>复制文件 <code>libmymath.so</code> 到一个标准的系统目录，例如：<code>/usr/lib64</code>， 然后运行 <code>ldconfig</code> 。<code>ldconfig</code> 命令创建所需的链接，并缓存到标准库目录中发现的最新共享库。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp libmymath.so /usr/lib64/</span></span>
<span class="line"><span>$ sudo ldconfig</span></span></code></pre></div><h3 id="编译应用程序" tabindex="-1">编译应用程序 <a class="header-anchor" href="#编译应用程序" aria-label="Permalink to “编译应用程序”">​</a></h3><p>从你的应用程序源文件代码（<code>mathDemo.c</code>）中创建一个名称为 <code>mathDemo.o</code> 的目标文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -I . -c mathDemo.c</span></span></code></pre></div><p><code>-I</code> 选项告诉 GCC 来在其后所列出的目录中搜索头文件（在这个示例中是 <code>mymath.h</code>）。在这个示例中，你指定的是当前目录，通过一个单点（<code>.</code>）来表示。创建一个可执行文件，使用 <code>-l</code> 选项来通过名称来引用你的共享数学库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -o mathDynamic mathDemo.o -lmymath</span></span></code></pre></div><p>GCC 会找到 <code>libmymath.so</code> ，因为它存在于一个默认的系统库目录中。使用 <code>ldd</code> 来查证所使用的共享库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ldd mathDemo</span></span>
<span class="line"><span>    linux-vdso.so.1 (0x00007fffe6a30000)</span></span>
<span class="line"><span>    libmymath.so =&gt; /usr/lib64/libmymath.so (0x00007fe4d4d33000)</span></span>
<span class="line"><span>    libc.so.6 =&gt; /lib64/libc.so.6 (0x00007fe4d4b29000)</span></span>
<span class="line"><span>    /lib64/ld-linux-x86-64.so.2 (0x00007fe4d4d4e000)</span></span></code></pre></div><p>看看 <code>mathDemo</code> 可执行文件的大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du ./mathDynamic</span></span>
<span class="line"><span>24   ./mathDynamic</span></span></code></pre></div><p>当然，它是一个小的应用程序，它所占用的磁盘空间量也反映了这一点。相比之下，相同代码的一个静态链接版本（正如你将在我后期的文章所看到的一样）是 932K !</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./mathDynamic</span></span>
<span class="line"><span>Enter two numbers</span></span>
<span class="line"><span>25</span></span>
<span class="line"><span>5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>25 + 5 = 30</span></span>
<span class="line"><span>25 - 5 = 20</span></span>
<span class="line"><span>25 * 5 = 125</span></span>
<span class="line"><span>25 / 5 = 5</span></span></code></pre></div><p>你可以使用 <code>file</code> 命令来查证它是动态链接的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file ./mathDynamic</span></span>
<span class="line"><span>./mathDynamic: ELF 64-bit LSB executable, x86-64,</span></span>
<span class="line"><span>dynamically linked,</span></span>
<span class="line"><span>interpreter /lib64/ld-linux-x86-64.so.2,</span></span>
<span class="line"><span>with debug_info, not stripped</span></span></code></pre></div><p>成功！</p><h3 id="动态链接" tabindex="-1">动态链接 <a class="header-anchor" href="#动态链接" aria-label="Permalink to “动态链接”">​</a></h3><p>因为链接发生在运行时，所以，使用一个共享库会产生一个轻量型的可执行文件。因为它在运行时解析引用，所以它会花费更多的执行时间。不过，因为在日常使用的 Linux 系统上绝大多数的命令是动态链接的，并且在现代硬件上，所能节省的时间是可以忽略不计的。对开发者和用户来说，它的固有模块性是一种强大的功能。</p><p>在这篇文章中，我描述了如何创建动态库，并将其链接到一个最终可执行文件。在我的下一篇文章中，我将使用相同的源文件代码来创建一个静态链接的可执行文件。</p><hr>`,20)),i("p",null,[s[13]||(s[13]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/22/5/dynamic-linking-modular-libraries-linux"},{default:p(()=>[...s[12]||(s[12]=[a("https://opensource.com/article/22/5/dynamic-linking-modular-libraries-linux",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jayashree-huttanagoudar"},{default:p(()=>[...s[14]||(s[14]=[a("Jayashree Huttanagoudar",-1)])]),_:1}),s[19]||(s[19]=a(" 选题：",-1)),e(n,{href:"https://github.com/lkxed"},{default:p(()=>[...s[15]||(s[15]=[a("lkxed",-1)])]),_:1}),s[20]||(s[20]=a(" 译者：",-1)),e(n,{href:"https://github.com/robsean"},{default:p(()=>[...s[16]||(s[16]=[a("robsean",-1)])]),_:1}),s[21]||(s[21]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[17]||(s[17]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[24]||(s[24]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[22]||(s[22]=[a("LCTT",-1)])]),_:1}),s[25]||(s[25]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[23]||(s[23]=[a("Linux中国",-1)])]),_:1}),s[26]||(s[26]=a(" 荣誉推出",-1))])])}const C=t(c,[["render",h]]);export{x as __pageData,C as default};
